{
 "summary": "`standardQuantumParallelRepetition` proves the qualitative conjecture: for every finite game G with finite-dimensional entangled value ω*(G) < 1, there are c, C > 0 with ω*(G^n) ≤ C·e^{-cn} for all n. `distributionUniformExponential` is meant to be Theorem 1.1, but it quantifies the constant universally (`∀ c, 0 < c ∧ …`) instead of existentially. As written it is false, since c = 0 or c = −1 violates `0 < c`, so it cannot be a faithful (or even provable) rendering of the paper's theorem. This is the single most important caveat.",
 "glossary": [
  {"decl": "Game", "line": 12, "plain": "A finite two-player one-round game: a probability distribution μ on X×Y and a Boolean predicate V(x,y,a,b).", "standard_concept": "nonlocal game (X,Y,A,B,μ,V)", "matches_standard": "yes", "note": ""},
  {"decl": "Game.repeat", "line": 23, "plain": "G^{⊗n}: product distribution on question tuples; the players win iff every coordinate wins.", "standard_concept": "n-fold parallel repetition", "matches_standard": "yes", "note": ""},
  {"decl": "DensityMatrix", "line": 50, "plain": "A PSD complex matrix with trace 1.", "standard_concept": "quantum state", "matches_standard": "yes", "note": ""},
  {"decl": "POVM", "line": 55, "plain": "A family of PSD effects summing to the identity.", "standard_concept": "POVM", "matches_standard": "yes", "note": ""},
  {"decl": "Strategy", "line": 60, "plain": "Finite-dimensional tensor-product entangled strategy: a shared (possibly mixed) state on H_A⊗H_B, with question-indexed POVMs on each side.", "standard_concept": "finite-dimensional entangled strategy", "matches_standard": "yes", "note": "Mixed shared states are allowed, which is equivalent to pure states by purification. The Hilbert spaces may be empty types, but then no trace-1 state exists."},
  {"decl": "Strategy.winProbability", "line": 87, "plain": "Σ μ(x,y) Σ_{a,b} V(x,y,a,b)·Re tr(ρ (A^x_a⊗B^y_b)).", "standard_concept": "winning probability", "matches_standard": "yes", "note": ""},
  {"decl": "entangledValue", "line": 94, "plain": "sSup of win probabilities over all finite-dimensional strategies.", "standard_concept": "ω*(G)", "matches_standard": "yes", "note": "The set is bounded by 1. It is empty only when A or B is empty, in which case the junk value 0 is used. The paper's exact definition of ω* is not in the excerpt."},
  {"decl": "repeatedEntangledValue", "line": 98, "plain": "ω*(G^{⊗n}).", "standard_concept": "ω*(G^{⊗n})", "matches_standard": "yes", "note": ""},
  {"decl": "HasExponentialBound", "line": 102, "plain": "∃ c>0, ∃ C>0, ∀ n, v n ≤ C·e^{-cn}.", "standard_concept": "exponential decay", "matches_standard": "partly", "note": "It allows a multiplicative constant C, whereas the paper's conjecture asks for ω*(G^n) ≤ e^{-c_G n} for n ≥ 1."},
  {"decl": "StandardQuantumParallelRepetition", "line": 108, "plain": "ω*(G) < 1 → ω*(G^n) has an exponential bound.", "standard_concept": "Quantum Parallel Repetition Conjecture", "matches_standard": "partly", "note": "The bound includes the extra constant C."}
 ],
 "lean_claims": [
  {"theorem": "distributionUniformExponential", "line": 112, "plain": "For EVERY real c: c > 0, and for all finite games G with A, B nonempty and ω*(G) < 1, and all n ≥ 1, ω*(G^n) ≤ exp(−c·ε^13/(ε+log(|A||B|))·n), where ε = 1 − ω*(G)."},
  {"theorem": "standardQuantumParallelRepetition", "line": 130, "plain": "For every finite game G (types in Type 0): if ω*(G) < 1, then ∃ c>0, C>0 with ω*(G^n) ≤ C·e^{-cn} for all n ∈ ℕ."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "There EXISTS a universal c_qs > 0 such that for every finite game with nonempty answer sets and ε = 1 − ω*(G) > 0, ω*(G^n) ≤ exp(−c_qs·ε^13/(ε+log|A||B|)·n) for all n ≥ 1."},
  {"ref": "Quantum Parallel Repetition Conjecture (answered affirmatively)", "plain": "For every finite G with ω*(G) < 1 there is c_G > 0 with ω*(G^n) ≤ exp(−c_G n) for all n ≥ 1."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1.1", "lean_theorem": "distributionUniformExponential", "relation": "different", "why": "The constant is quantified ∀ instead of ∃, which makes the statement false and not equivalent to the paper's theorem."},
  {"paper_ref": "Quantum Parallel Repetition Conjecture", "lean_theorem": "standardQuantumParallelRepetition", "relation": "lean_weaker", "why": "An extra constant C is allowed. This is mathematically recoverable using ω*(G^n) < 1 for n ≥ 1, but not literally the same statement."}
 ],
 "flags": [
  {"id": "F1", "category": "quantifier", "severity": "high", "decl": "distributionUniformExponential", "line": 113, "paper_ref": "Theorem 1.1", "explanation": "The statement reads `∀ c : ℝ, 0 < c ∧ …` where the paper has 'there exists a universal constant c_qs > 0'. Instantiating c = 0 demands 0 < 0, so the Lean statement is false. It therefore cannot express Theorem 1.1, and any claimed proof must be suspect (sorry, or an inconsistency).", "polarity": "lean stronger", "probe_idea": "theorem neg : ¬ (∀ c : ℝ, 0 < c ∧ True) := fun h => lt_irrefl _ (h 0).1 — more precisely, prove ¬(statement of distributionUniformExponential) by specializing c := 0."},
  {"id": "F2", "category": "other", "severity": "low", "decl": "HasExponentialBound", "line": 102, "paper_ref": "Quantum Parallel Repetition Conjecture", "explanation": "There is an extra multiplicative constant C > 0, and the bound runs over all n including 0. The paper's form has no C and n ≥ 1. Removing C requires knowing ω*(G^n) < 1 for each n ≥ 1, which the Lean statement does not give.", "polarity": "lean weaker", "probe_idea": "Prove HasExponentialBound v ∧ (∀ n ≥ 1, v n < 1) → ∃ c>0, ∀ n ≥ 1, v n ≤ exp(-c n)."},
  {"id": "F3", "category": "type-default", "severity": "low", "decl": "standardQuantumParallelRepetition", "line": 131, "paper_ref": null, "explanation": "The game types are restricted to Type (universe 0), and strategy spaces to Type. This is harmless for finite games.", "polarity": "lean weaker", "probe_idea": null}
 ],
